package es.gestionpersonas.seguridad.servicio;
import es.gestionpersonas.comun.*; import es.gestionpersonas.seguridad.dto.MfaDtos; import es.gestionpersonas.seguridad.modelo.PoliticaMfa; import es.gestionpersonas.seguridad.repositorio.RepositorioPoliticaMfa; import es.gestionpersonas.seguridad.web.AccesoActual; import jakarta.persistence.EntityManager; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional(readOnly=true)
public class ServicioPoliticaMfa {
 private final RepositorioPoliticaMfa repo; private final EntityManager em;
 public ServicioPoliticaMfa(RepositorioPoliticaMfa repo,EntityManager em){this.repo=repo;this.em=em;}
 public OptionalInt minutosContexto(AccesoActual a){return coincidentes(a,null).stream().filter(p->p.getPermisoId()==null).mapToInt(PoliticaMfa::getMinutosValidez).min();}
 public OptionalInt minutosPermiso(AccesoActual a,String permiso){return coincidentes(a,permiso).stream().filter(p->p.getPermisoId()!=null).mapToInt(PoliticaMfa::getMinutosValidez).min();}
 private List<PoliticaMfa> coincidentes(AccesoActual a,String permiso){if(a==null)return List.of(); Long roleId=rolId(a.roleCode()); Long permisoId=permiso==null?null:permisoId(permiso); return repo.findByActivoTrueOrderByIdAsc().stream().filter(p->p.getEntidadContextoId()==null||Objects.equals(p.getEntidadContextoId(),a.contextEntityId())).filter(p->p.getRolSeguridadId()==null||Objects.equals(p.getRolSeguridadId(),roleId)).filter(p->p.getPermisoId()==null||Objects.equals(p.getPermisoId(),permisoId)).toList();}
 private Long rolId(String codigo){if(codigo==null)return null; List<?> r=em.createNativeQuery("select id from rol_seguridad where codigo=:c").setParameter("c",codigo).getResultList();return r.isEmpty()?null:((Number)r.get(0)).longValue();}
 private Long permisoId(String codigo){List<?> r=em.createNativeQuery("select id from permiso where codigo=:c").setParameter("c",codigo).getResultList();return r.isEmpty()?null:((Number)r.get(0)).longValue();}
 public List<MfaDtos.VistaPolitica> listar(AccesoActual acceso){return repo.findAll().stream().filter(p->puedeGestionar(acceso,p)).map(this::vista).toList();}
 @Transactional public MfaDtos.VistaPolitica crear(AccesoActual acceso,MfaDtos.SolicitudPolitica d){validar(d);validarGestion(acceso,d.entidadContextoId());return vista(repo.save(new PoliticaMfa(d.entidadContextoId(),d.rolSeguridadId(),permisoIdNullable(d.codigoPermiso()),d.minutosValidez()==null?480:d.minutosValidez(),d.activo()==null||d.activo())));}
 @Transactional public MfaDtos.VistaPolitica actualizar(AccesoActual acceso,Long id,MfaDtos.SolicitudPolitica d){validar(d);PoliticaMfa p=repo.findById(id).orElseThrow(()->new ExcepcionNoEncontrado("Política MFA no encontrada"));if(!puedeGestionar(acceso,p))throw new ExcepcionProhibido("La política MFA queda fuera del contexto administrable");validarGestion(acceso,d.entidadContextoId());p.actualizar(d.entidadContextoId(),d.rolSeguridadId(),permisoIdNullable(d.codigoPermiso()),d.minutosValidez()==null?480:d.minutosValidez(),d.activo()==null||d.activo());return vista(p);}
 @Transactional public void eliminar(AccesoActual acceso,Long id){PoliticaMfa p=repo.findById(id).orElseThrow(()->new ExcepcionNoEncontrado("Política MFA no encontrada"));if(!puedeGestionar(acceso,p))throw new ExcepcionProhibido("La política MFA queda fuera del contexto administrable");repo.delete(p);}
 private boolean esAdminPlataforma(AccesoActual a){return a!=null&&"ADMIN_PLATAFORMA".equalsIgnoreCase(a.roleCode());}
 private boolean puedeGestionar(AccesoActual a,PoliticaMfa p){return esAdminPlataforma(a)||(a!=null&&p.getEntidadContextoId()!=null&&Objects.equals(a.contextEntityId(),p.getEntidadContextoId()));}
 private void validarGestion(AccesoActual a,Long contextoObjetivo){if(esAdminPlataforma(a))return;if(a==null||contextoObjetivo==null||!Objects.equals(a.contextEntityId(),contextoObjetivo))throw new ExcepcionProhibido("Un administrador de organización solo puede gestionar políticas MFA de su contexto activo");}
 private void validar(MfaDtos.SolicitudPolitica d){if(d.entidadContextoId()==null&&d.rolSeguridadId()==null&&(d.codigoPermiso()==null||d.codigoPermiso().isBlank()))throw new IllegalArgumentException("La política MFA debe indicar contexto, rol, permiso o una combinación"); if(d.codigoPermiso()!=null&&!d.codigoPermiso().isBlank()&&permisoIdNullable(d.codigoPermiso())==null)throw new IllegalArgumentException("Permiso MFA desconocido: "+d.codigoPermiso());}
 private Long permisoIdNullable(String c){return c==null||c.isBlank()?null:permisoId(c);}
 private MfaDtos.VistaPolitica vista(PoliticaMfa p){String rol=null,perm=null;if(p.getRolSeguridadId()!=null){List<?>x=em.createNativeQuery("select codigo from rol_seguridad where id=:i").setParameter("i",p.getRolSeguridadId()).getResultList();if(!x.isEmpty())rol=String.valueOf(x.get(0));}if(p.getPermisoId()!=null){List<?>x=em.createNativeQuery("select codigo from permiso where id=:i").setParameter("i",p.getPermisoId()).getResultList();if(!x.isEmpty())perm=String.valueOf(x.get(0));}return new MfaDtos.VistaPolitica(p.getId(),p.getEntidadContextoId(),p.getRolSeguridadId(),rol,perm,p.getMinutosValidez(),p.isActivo());}
}
